-- 0065: (1) ربط بنود المقطوعية ببنود المرجع الفني لتُولَّد منها ورقة «المواصفات الفنية» في Excel بدل تكرار الأوصاف
-- (2) اشتراطات تسليم المشروع على المقاول (HO-NN) تُرفق بجدول الكميات وتُولَّد منها بنود الإغلاق. قابل لإعادة التشغيل.
alter table public.ls_items add column if not exists refs text[] not null default '{}';
alter table public.boq_lines add column if not exists ls_code text;
alter table public.boq_lines add column if not exists refs text[];
alter table public.boqs add column if not exists handover boolean not null default true;
-- ربط سطور المقطوعية القائمة ببندها في القائمة (بالعنوان)
update public.boq_lines l set ls_code = i.code from public.ls_items i where l.kind = 'free' and l.ls_code is null and l.title = i.title;

create table if not exists public.handover_reqs (
  code text primary key, grp text not null, title text not null, descr text not null default '', deliver text default '', stage text default '',
  sort int default 0, active boolean not null default true, updated_at timestamptz default now()
);
alter table public.handover_reqs enable row level security;
grant select, insert, update, delete on public.handover_reqs to authenticated;
drop policy if exists p_read on public.handover_reqs; create policy p_read on public.handover_reqs for select using (public.can_read());
drop policy if exists p_admin on public.handover_reqs; create policy p_admin on public.handover_reqs for all using (public.my_role() = 'admin') with check (public.my_role() = 'admin');

