  update public.ls_items set refs = array['04 22 13','04 22 19','04 22 23','04 22 26','04 22 29','04 22 33','08 11 13','08 11 16','08 11 19','08 12 13','08 12 16','08 14 16','08 14 19','08 14 23','08 14 33','08 14 73','08 51 13','08 71 13','08 71 16','08 71 19','08 71 21','08 71 23','08 71 26','08 71 29','08 71 33','08 71 36','08 71 39','08 71 43','09 05 61','09 05 71','09 21 16','09 21 19','09 21 23','09 21 33','09 21 36','09 21 39','09 22 13','09 22 16','09 22 26','09 22 36','09 30 13','09 30 19','09 30 23','09 30 26','09 30 33','09 30 36','09 30 43','09 51 13','09 51 23','09 51 33','09 51 53','09 53 23','09 53 26','09 54 13','09 54 16','09 54 23','09 54 26','09 54 33','09 54 36','09 54 43','09 65 13','09 65 16','09 65 19','09 65 26','09 65 43','09 66 13','09 66 16','09 66 23','09 75 13','09 77 13','09 77 23','09 77 33','09 77 43','09 77 46','09 77 53','09 77 59','09 78 13','09 78 16','09 78 23','09 91 13','09 91 23','09 91 26','09 96 56','09 96 66','10 26 13','10 26 16','10 26 19','10 26 23','10 26 33','10 26 36','10 26 46','10 26 49','26 51 13','26 51 16','26 51 19','26 51 23','26 51 26','26 51 29','26 51 33','26 51 36','26 51 39','26 52 13','26 52 16']::text[] where code = 'LS-01' and refs = '{}';
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-01',$q$الوثائق والمخططات$q$,$q$المخططات كما نُفِّذ (As-Built)$q$,$q$يسلّم المقاول مخططات كما نُفِّذ لجميع التخصصات (معماري، إنشائي، كهرباء، تيار خفيف، ميكانيكا، صحي، إطفاء، غازات طبية، موقع عام) تعكس الوضع النهائي الفعلي بما فيه مسارات التمديدات المخفية ومواقع المحابس واللوحات ونقاط الفحص، معتمدة وموقعة من المقاول والمهندس المشرف، وبترقيم الغرف المعتمد من التجمع.$q$,$q$ملفات CAD (DWG) قابلة للتعديل + PDF موقّع + نسختان ورقيتان A1 مجلدتان$q$,$q$قبل الاستلام الابتدائي$q$,10) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-02',$q$الوثائق والمخططات$q$,$q$الرسومات التنفيذية المعتمدة وسجل الاعتمادات$q$,$q$يسلّم المقاول المجموعة النهائية للرسومات التنفيذية (Shop Drawings) المعتمدة، وسجل الاعتمادات (Submittal Register) بجميع طلبات الاعتماد وحالتها وتواريخها، وسجل طلبات الاستيضاح (RFI) وأوامر التغيير.$q$,$q$PDF مفهرس + سجل Excel$q$,$q$قبل الاستلام الابتدائي$q$,20) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-03',$q$الوثائق والمخططات$q$,$q$سجل المواد المنفذة$q$,$q$يسلّم المقاول سجلاً بجميع المواد والمعدات المركّبة فعلياً: اسم المنتج، المصنّع، الموديل، اللون ورقم التشطيب ورقم الدفعة (Batch) حيث ينطبق، المورد وبيانات التواصل، ومرجع اعتماد المادة؛ لتسهيل الصيانة والاستبدال المطابق مستقبلاً.$q$,$q$Excel + البيانات الفنية PDF$q$,$q$قبل الاستلام الابتدائي$q$,30) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-04',$q$الوثائق والمخططات$q$,$q$التوثيق المصوّر للأعمال المخفية$q$,$q$يوثّق المقاول بالصور المؤرخة جميع الأعمال قبل إخفائها (داخل الأسقف والجدران وتحت الأرضيات والعزل) مصنفة حسب الموقع والتخصص، ويسلّمها مفهرسة مع المخططات كما نُفِّذ.$q$,$q$مجلد صور مفهرس حسب المبنى/الدور/الغرفة$q$,$q$قبل الاستلام الابتدائي$q$,40) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-05',$q$التشغيل والصيانة$q$,$q$كتيبات التشغيل والصيانة (O&M)$q$,$q$يسلّم المقاول كتيبات التشغيل والصيانة لكل نظام ومعدة باللغتين العربية والإنجليزية حيث أمكن، تشمل: وصف النظام، طريقة التشغيل والإيقاف، الصيانة الدورية وجداولها، الأعطال الشائعة وحلولها، قائمة قطع الغيار، المخططات والكتالوجات، وبيانات الوكيل والدعم الفني.$q$,$q$نسختان ورقيتان مجلدتان مفهرستان + PDF قابل للبحث$q$,$q$قبل الاستلام الابتدائي$q$,50) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-06',$q$التشغيل والصيانة$q$,$q$جدول الصيانة الوقائية للأصول$q$,$q$يعدّ المقاول جدول صيانة وقائية مقترحاً لكل أصل وفق توصيات المصنّع (المهمة، التكرار، المدة، المهارة المطلوبة، قطع الغيار المستهلكة) بالقالب المعتمد لدى إدارة الخدمات الفنية حتى يُستورد في منصة الصيانة مباشرة.$q$,$q$Excel بالقالب المعتمد$q$,$q$قبل الاستلام الابتدائي$q$,60) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-07',$q$التشغيل والصيانة$q$,$q$قطع الغيار والمواد الاحتياطية$q$,$q$يورّد المقاول قطع الغيار الموصى بها من المصنّعين لتشغيل سنتين للأنظمة الحرجة، وكميات احتياطية من مواد التشطيب من نفس الدفعة لا تقل عن: 2% من البلاط والأرضيات، 2% من بلاطات الأسقف المستعارة، 5% من كل لون دهان بعبوات مغلقة موسومة، مع قائمة تسليم موقعة.$q$,$q$المواد موسومة ومخزنة في الموقع المحدد + قائمة تسليم$q$,$q$عند الاستلام الابتدائي$q$,70) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-08',$q$التشغيل والصيانة$q$,$q$العدد والأدوات الخاصة$q$,$q$يسلّم المقاول العدد والأدوات الخاصة اللازمة لتشغيل وصيانة المعدات (مفاتيح اللوحات، أدوات المصاعد، برمجيات وكابلات البرمجة، كلمات المرور الإدارية للأنظمة) مع قائمة تسليم.$q$,$q$قائمة تسليم موقعة$q$,$q$عند الاستلام الابتدائي$q$,80) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-09',$q$التشغيل والصيانة$q$,$q$تدريب فرق التشغيل والصيانة$q$,$q$يدرّب المقاول ووكلاء المعدات فرق التشغيل والصيانة والأمن والسلامة على تشغيل الأنظمة وصيانتها والتعامل مع الطوارئ، بجلسات نظرية وعملية في الموقع، مع مادة تدريبية وتسجيل مرئي للجلسات وكشوف حضور موقعة.$q$,$q$خطة تدريب معتمدة + كشوف حضور + المادة والتسجيلات$q$,$q$قبل الاستلام الابتدائي$q$,90) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-10',$q$التشغيل والصيانة$q$,$q$بيانات دليل المنشأة$q$,$q$يزوّد المقاول إدارة الخدمات الفنية بالبيانات اللازمة لإصدار دليل التشغيل والصيانة ودليل مستخدمي المنشأة (R-42): قوائم الأنظمة والمعدات ومواقعها، نقاط الإغلاق والعزل، جهات الاتصال والضمان، والتعليمات الخاصة.$q$,$q$وفق قالب دليل المنشأة في المنصة$q$,$q$قبل الاستلام الابتدائي$q$,100) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-11',$q$الضمانات والشهادات$q$,$q$ضمان الأعمال العام$q$,$q$يقدّم المقاول ضماناً عاماً لجميع الأعمال والمواد لمدة لا تقل عن سنة من تاريخ الاستلام الابتدائي ما لم ينص العقد أو المواصفات على مدة أطول، يلتزم خلالها بإصلاح أي عيب أو استبداله على حسابه.$q$,$q$خطاب ضمان رسمي مختوم$q$,$q$عند الاستلام الابتدائي$q$,110) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-12',$q$الضمانات والشهادات$q$,$q$ضمانات المصنّعين وجدول الضمانات$q$,$q$يسلّم المقاول ضمانات المصنّعين والوكلاء صادرة باسم تجمع الأحساء الصحي، وجدولاً موحداً يبين لكل نظام ومعدة: مدة الضمان، تاريخ البدء والانتهاء، الجهة الضامنة وبيانات التواصل. ومن المدد الدنيا: العزل المائي للأسطح 10 سنوات، المصاعد سنتان، ضواغط التكييف 5 سنوات، وحدات الإنارة LED 5 سنوات، أجهزة الأبواب الآلية سنتان.$q$,$q$أصول الضمانات + جدول Excel$q$,$q$عند الاستلام الابتدائي$q$,120) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-13',$q$الضمانات والشهادات$q$,$q$شهادات الاختبار والتشغيل$q$,$q$يسلّم المقاول تقارير الاختبار والتشغيل لجميع الأنظمة بحضور ممثل التجمع: اختبارات العزل والتأريض الكهربائي، الضغط للمواسير والإطفاء، جودة المياه والتعقيم، موازنة الهواء والمياه (TAB)، شهادة الغازات الطبية من جهة ثالثة، شهادة المصاعد من جهة فحص معتمدة، واختبار إنذار الحريق جهازاً جهازاً.$q$,$q$تقارير موقعة PDF + الأصول$q$,$q$قبل الاستلام الابتدائي$q$,130) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-14',$q$الضمانات والشهادات$q$,$q$شهادات الجهات الرسمية$q$,$q$يستخرج المقاول على حسابه شهادات وموافقات الجهات الرسمية اللازمة للتشغيل (الدفاع المدني، البلدية، شركة الكهرباء، شركة المياه، وغيرها حسب طبيعة المشروع) ويسلّم أصولها.$q$,$q$أصول الشهادات$q$,$q$قبل الاستلام الابتدائي$q$,140) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-15',$q$الضمانات والشهادات$q$,$q$شهادات مطابقة المواد$q$,$q$يسلّم المقاول شهادات المطابقة للمواد والمنتجات الخاضعة للوائح الفنية (SASO) وشهادات التصنيف للحريق للأبواب ومانعات الحريق والزجاج المصنف، مطابقة لما رُكّب فعلاً.$q$,$q$PDF مفهرس$q$,$q$قبل الاستلام الابتدائي$q$,150) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-16',$q$الترميز والتوسيم$q$,$q$ترميز الأصول وسجلها$q$,$q$يرقّم المقاول جميع المعدات والأصول الكهروميكانيكية والطبية بلوحات دائمة مقاومة للحرارة والتطهير تحمل رمز QR وفق نظام الترميز المعتمد في التجمع (رمز الموقع في Planon / المبنى / الدور / الغرفة / نوع الأصل / الرقم التسلسلي)، ويسلّم سجل الأصول (الاسم، النوع، المصنّع، الموديل، الرقم التسلسلي، الموقع، تاريخ التركيب، انتهاء الضمان، المورد) بقالب المنصة.$q$,$q$لوحات مركبة + سجل Excel بقالب المنصة$q$,$q$قبل الاستلام الابتدائي$q$,160) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-17',$q$الترميز والتوسيم$q$,$q$ترقيم الغرف والفراغات$q$,$q$يطبق المقاول ترقيم الغرف والفراغات المعتمد من التجمع على الأبواب واللوحات والمخططات كما نُفِّذ ولوحات الكهرباء وأجهزة إنذار الحريق، بحيث يتطابق الرقم في كل الوثائق والموقع.$q$,$q$جدول الغرف + التطبيق بالموقع$q$,$q$قبل الاستلام الابتدائي$q$,170) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-18',$q$الترميز والتوسيم$q$,$q$توسيم الأنظمة الكهروميكانيكية$q$,$q$يوسّم المقاول: جداول الدوائر داخل كل لوحة كهربائية، الكابلات من الطرفين، المخارج الكهربائية والبيانات برقم الدائرة/المنفذ، المواسير بألوان التمييز وأسهم اتجاه السريان، المحابس بلوحات مرقمة مع مخطط المحابس، مجاري الهواء، ومخارج الغازات الطبية؛ ويسلّم قائمة عناوين أجهزة إنذار الحريق.$q$,$q$التوسيم بالموقع + مخطط المحابس + جداول الدوائر$q$,$q$قبل الاستلام الابتدائي$q$,180) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-19',$q$الترميز والتوسيم$q$,$q$المفاتيح وبطاقات الدخول$q$,$q$يسلّم المقاول جميع المفاتيح موسومة برقم الغرفة وفق نظام المفاتيح الرئيسية (Master Key) المعتمد، مع جدول المفاتيح، وبطاقات الدخول مبرمجة حسب الصلاحيات المعتمدة، وكلمات المرور الإدارية لأنظمة التحكم بالدخول.$q$,$q$لوحة مفاتيح + جدول + محضر تسليم$q$,$q$عند الاستلام الابتدائي$q$,190) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-20',$q$الاستلام والنظافة والسجلات$q$,$q$التنظيف النهائي$q$,$q$ينفّذ المقاول تنظيفاً نهائياً شاملاً للأرضيات والجدران والأسقف والنوافذ والتجهيزات ومجاري الهواء والفلاتر، وتنظيفاً نهائياً وفق متطلبات مكافحة العدوى للمناطق السريرية قبل التسليم، مع إزالة جميع المخلفات من الموقع.$q$,$q$محضر فحص النظافة$q$,$q$عند الاستلام الابتدائي$q$,200) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-21',$q$الاستلام والنظافة والسجلات$q$,$q$إزالة المؤقتات وإعادة الأوضاع$q$,$q$يزيل المقاول جميع المنشآت والحواجز والتوصيلات المؤقتة، ويصلح أي ضرر لحق بالمناطق المجاورة أو المسارات أو التشطيبات القائمة ويعيدها لحالتها.$q$,$q$محضر فحص$q$,$q$عند الاستلام الابتدائي$q$,210) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-22',$q$الاستلام والنظافة والسجلات$q$,$q$قائمة الملاحظات وإغلاقها$q$,$q$يُعدّ محضر الاستلام الابتدائي بقائمة ملاحظات (Snag List) مرقمة ومصورة، ويغلقها المقاول خلال المدة المحددة، ويُوقّع محضر الإغلاق.$q$,$q$قائمة الملاحظات + محضر الإغلاق$q$,$q$عند الاستلام الابتدائي$q$,220) on conflict (code) do nothing;
  insert into public.handover_reqs(code,grp,title,descr,deliver,stage,sort) values ('HO-23',$q$الاستلام والنظافة والسجلات$q$,$q$براءات الذمة والمطالبات$q$,$q$يقدّم المقاول براءات ذمة من مقاولي الباطن والموردين الرئيسيين وسداد فواتير الخدمات المؤقتة، وإقراراً بعدم وجود مطالبات قبل صرف المستخلص الختامي.$q$,$q$أصول الإقرارات$q$,$q$قبل الاستلام النهائي$q$,230) on conflict (code) do nothing;
